shell_commands:
cat << 'EOF' > test-plan.ts
import fs from 'fs';

const content = fs.readFileSync('src/orchestration/chatOrchestrator.test.ts', 'utf-8');

const newTest = `
  it('sums usage across multiple provider calls', async () => {
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, totalUsage) => {
        seen = totalUsage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 3, totalTokens: 8}}],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual({inputTokens: 15, outputTokens: 5, totalTokens: 20});
  });
`;

const updatedContent = content.replace(
  "it('keeps the usage an earlier round reported when a later round reports none'",
  newTest + "\n  it('keeps the usage an earlier round reported when a later round reports none'"
);

fs.writeFileSync('src/orchestration/chatOrchestrator.test.ts', updatedContent);
EOF
node test-plan.ts
rm test-plan.ts
npx vitest run src/orchestration/chatOrchestrator.test.ts
